/**
 * The network panel's vocabulary, shared by the browser and the worker.
 *
 * The panel measures download throughput against this deployment. Its payload is generated by the
 * Worker itself, so the measurement needs no third-party host, no CORS grant and no relaxation of the
 * page's `connect-src`. Custom addresses stay available for a deployment that has widened that policy
 * itself; the client and the route validate them with the same function.
 */

/** Which node is the deployment's own download endpoint rather than a row the reader saved. */
export const BUILTIN_NODE_ID = 'builtin'

export const DOWNLOAD_PATH = '/api/tools/network-panel/download'

export const NETWORK_PANEL_LIMITS = {
  minThreads: 1,
  maxThreads: 64,
  maxLabel: 60,
  maxUrl: 2048,
  maxNodes: 50,
  runPageDefault: 30,
  runPageMax: 100,
  runRetention: 500,
  downloadBytesMin: 1,
  downloadBytesMax: 64 * 1024 * 1024,
  downloadBytesPreferred: 32 * 1024 * 1024,
  maxDataBytes: 1024 ** 5,
  maxSpeedBps: 10 * 1024 ** 3,
} as const

export type StopReason = 'manual' | 'data_cap' | 'hidden' | 'failed'

export const STOP_REASONS: readonly StopReason[] = ['manual', 'data_cap', 'hidden', 'failed']

export interface NetworkPanelSettings {
  threads: number
  autoStart: boolean
  background: boolean
  showChart: boolean
  saveHistory: boolean
  autoRefreshInfo: boolean
  maxDataBytes: number
  maxSpeedBps: number
  nodeId: string
}

export const DEFAULT_NETWORK_PANEL_SETTINGS: NetworkPanelSettings = {
  threads: 8,
  autoStart: false,
  background: false,
  showChart: false,
  saveHistory: true,
  autoRefreshInfo: true,
  maxDataBytes: 0,
  maxSpeedBps: 0,
  nodeId: BUILTIN_NODE_ID,
}

export interface NetworkPanelNode {
  id: string
  label: string
  url: string
  created_at: number
}

export interface NetworkPanelRun {
  id: string
  node_label: string
  node_url: string
  bytes_used: number
  avg_speed_bps: number
  duration_ms: number
  threads: number
  stop_reason: StopReason
  created_at: number
}

export interface NetworkPanelRunSummary {
  count: number
  bytes: number
  best_speed_bps: number
  avg_speed_bps: number
}

export interface NetworkPanelHistory {
  items: NetworkPanelRun[]
  total: number
  summary: NetworkPanelRunSummary
}

/** What this deployment can honestly say about the reader's connection. */
export interface NetworkPanelInfo {
  ip: string | null
  country: string | null
  region: string | null
  city: string | null
  isp: string | null
  asn: number | null
  colo: string | null
  /** False when the request carried no edge metadata (a local `wrangler`/Vite run, mostly). */
  edge_geo: boolean
  observed_at: number
}

export interface NetworkPanelRunInput {
  node_label: string
  node_url: string
  bytes_used: number
  avg_speed_bps: number
  duration_ms: number
  threads: number
  stop_reason: StopReason
}

export interface SpeedSeriesPoint {
  /** Unix time in seconds. */
  t: number
  /** Bytes per second. */
  v: number
}

/** The live reading the view draws while a test is running. */
export interface SpeedProgress {
  bytesUsed: number
  elapsedMs: number
  speedBps: number
  series: SpeedSeriesPoint[]
}

export type NodeUrlProblem = 'empty' | 'invalid' | 'scheme'

export type NodeUrlParseResult =
  | { ok: true; url: string }
  | { ok: false; problem: NodeUrlProblem }
